<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,computed,watch,nextTick} from 'vue';
import EmojiPicker from './EmojiPicker.vue';
import VoiceMessage from './VoiceMessage.vue';
import {parseChatDate} from './chatTime';
import VoiceRecorder from './VoiceRecorder.vue';
import EncryptedVoiceCall from './EncryptedVoiceCall.vue';
import {localDevice,newDevice,conversationCode,confirmConversation,trusted,encrypt,decrypt,base64,unbase64,type LocalDevice,type Device,type Payload,type CallSignal} from './encryptedCrypto';
const props=withDefaults(defineProps<{legacy?:boolean;csrf?:string;threadId?:string;canCall?:boolean;regularChats?:{id:number;name:string;preview:string}[]}>(),{canCall:true});
const emit=defineEmits<{directory:[threads:any[]];incoming:[threadId:string];close:[];callActive:[active:boolean];selected:[id:string];activity:[id:string];regular:[id:number]}>();
const privateCall=ref<InstanceType<typeof EncryptedVoiceCall>|null>(null),callActive=ref(false),voiceRecording=ref(false);const seenSignals=new Set<string>();function callState(value:boolean){callActive.value=value;emit('callActive',value);}
const data=ref<any>(null),device=ref<LocalDevice|null>(null),active=ref<any>(null),error=ref(''),busy=ref(false),loading=ref(false),target=ref(''),securityCode=ref(''),compared=ref(false),securityOpen=ref(false),newChat=ref(false),chatFilter=ref(''),copyNotice=ref(''),verified=ref(false),draft=ref(''),file=ref<File|null>(null),fileInput=ref<HTMLInputElement|null>(null),rows=ref<any[]>([]),more=ref(false);
let closed=false,generation=0;const urls=new Set<string>();const peer=computed<Device|undefined>(()=>active.value?.devices.find((d:Device)=>d.id!==device.value?.id));
async function api(path='',body?:unknown){const response=await fetch('/communication/api/encrypted'+path,{method:body?'POST':'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined,cache:'no-store'});const result=await response.json();if(!response.ok)throw Error(result.errors?Object.values(result.errors).flat().join(' '):result.message||'Encrypted chat unavailable.');return result;}
function cleanup(){for(const url of urls)URL.revokeObjectURL(url);urls.clear();rows.value=[];}
async function refresh(){if(!isSecureContext||!crypto.subtle)throw Error('Encrypted chat requires HTTPS or localhost. Plain HTTP on a network address is not supported.');const result=await api();if(closed)return;if(!Array.isArray(result.threads)||!Array.isArray(result.people)||typeof result.principal!=='string')throw Error('Encrypted chat data is unavailable.');data.value=result;emit('directory',result.threads);const local=await localDevice(result.principal);if(closed)return;if(result.device){if(!local||local.id!==result.device.id||local.public_key!==result.device.public_key){device.value=null;throw Error('This account is registered on another browser profile. Use that original profile; lost device keys cannot be recovered by an administrator.');}device.value=local;}if(active.value){const thread=result.threads.find((t:any)=>t.id===active.value.id);if(!thread){active.value=null;cleanup();}else{active.value=thread;const other=thread.devices.find((d:Device)=>d.id!==local?.id);verified.value=!!local&&!!other&&await trusted(local,other);if(other){if(local){const code=await conversationCode(local,other,thread.id);if(code!==securityCode.value){compared.value=false;securityCode.value=code;}}}if(!verified.value)cleanup();}}}
async function setup(){busy.value=true;error.value='';try{const local=await newDevice(data.value.principal);await api('/devices',{id:local.id,public_key:local.public_key});await refresh();if(props.threadId){const thread=data.value.threads.find((t:any)=>t.id===props.threadId);if(thread)await open(thread);}}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function open(thread:any){if(callActive.value&&active.value?.id!==thread.id){error.value='End the private call before switching conversations.';return;}generation++;cleanup();active.value=thread;emit('selected',thread.id);draft.value='';file.value=null;securityCode.value='';compared.value=false;securityOpen.value=false;newChat.value=false;verified.value=false;error.value='';const other=thread.devices.find((d:Device)=>d.id!==device.value?.id);if(!other){return;}if(device.value)securityCode.value=await conversationCode(device.value,other,thread.id);verified.value=!!device.value&&await trusted(device.value,other);if(verified.value)await loadMessages();}
async function verify(){if(!device.value||!peer.value||!compared.value)return;busy.value=true;error.value='';try{if(!compared.value)throw Error('Compare the security codes with the other participant first.');await confirmConversation(device.value,peer.value,active.value.id,securityCode.value);verified.value=true;compared.value=false;securityOpen.value=false;await loadMessages();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function start(){if(!target.value||busy.value)return;busy.value=true;error.value='';try{const person=data.value.people.find((p:any)=>p.id===Number(target.value));const result=await api('/threads',{peer_user_id:person.id,...(person.device_id?{peer_device_id:person.device_id}:{})});await refresh();await open(data.value.threads.find((t:any)=>t.id===result.id));}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function loadMessages(older=false){if(!active.value||!device.value||!verified.value)return;const thread=active.value,version=++generation,previousUrls=new Set(urls),createdUrls=new Set<string>();loading.value=true;try{const result=await api('/threads/'+thread.id+'/messages'+(older&&rows.value.length?'?before='+rows.value[0].id:''));const decoded=[];for(const row of result.messages){try{const sender=thread.devices.find((d:Device)=>d.id===row.sender_device_id);if(!sender)throw Error('Unknown sender');const payload=await decrypt(device.value,sender,thread.id,row.id,row.envelopes);let url='';if(payload.file){const bytes=unbase64(payload.file.data);if(bytes.length>1048576)throw Error('Attachment too large');url=URL.createObjectURL(new Blob([bytes],{type:['image/png','image/jpeg','image/webp','application/pdf','audio/webm','audio/webm;codecs=opus','audio/ogg','audio/ogg;codecs=opus','audio/mpeg','audio/wav','audio/mp4'].includes(payload.file.type)?payload.file.type:'application/octet-stream'}));urls.add(url);createdUrls.add(url);}decoded.push({...row,payload,url});}catch{decoded.push({...row,failed:true});}}if(closed||version!==generation||active.value?.id!==thread.id){for(const url of createdUrls){URL.revokeObjectURL(url);urls.delete(url);}return;}if(!older)for(const url of previousUrls){URL.revokeObjectURL(url);urls.delete(url);}rows.value=older?[...decoded,...rows.value]:decoded;
 more.value=result.more;
}catch(e){if(version===generation)error.value=(e as Error).message;}finally{if(version===generation)loading.value=false;}}
async function send(){if(!device.value||!active.value||!verified.value||busy.value||(!draft.value.trim()&&!file.value))return;busy.value=true;error.value='';try{if(!await trusted(device.value,peer.value!))throw Error('Verify the participant device again.');if(file.value&&file.value.size>1048576)throw Error('Encrypted attachments must be 1 MB or smaller.');const payload:Payload={text:draft.value};if(file.value)payload.file={name:file.value.name,type:file.value.type,data:base64(await file.value.arrayBuffer())};const id=crypto.randomUUID(),thread=active.value;const envelopes=await encrypt(device.value,thread.devices,thread.id,id,payload);await api('/threads/'+thread.id+'/messages',{id,envelopes});draft.value='';file.value=null;if(fileInput.value)fileInput.value.value='';await loadMessages();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function sendControl(signal:CallSignal){const local=device.value,thread=active.value;if(!local||!thread||!peer.value||!await trusted(local,peer.value))throw Error('Verify the participant device before calling.');const id=crypto.randomUUID();const envelopes=await encrypt(local,thread.devices,thread.id,id,{text:'',signal},'signal');await api('/threads/'+thread.id+'/signals',{id,envelopes});}
const chatName=computed(()=>active.value?(data.value?.can_create?active.value.peer_name:'Super Admin'):'Private chat');
function initials(name:string){return name.split(/\s+/).filter(Boolean).slice(0,2).map(value=>value[0]).join('').toUpperCase();}
function time(value:string){return parseChatDate(value).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}
async function copyCode(){try{await navigator.clipboard.writeText(securityCode.value);copyNotice.value='Security code copied. Compare it using a trusted channel.';}catch{copyNotice.value='Select the security code to copy it.';}}
function onEnter(event:KeyboardEvent){if(!event.shiftKey&&!event.isComposing){event.preventDefault();void send();}}
async function voiceReady(recording:File){file.value=recording;await send();}
async function live(event:Event){if(closed)return;const detail=(event as CustomEvent).detail,id=detail?.thread_id;try{await refresh();if(id&&!detail?.signal_id&&data.value.threads.some((t:any)=>t.id===id))emit('activity',id);if(detail?.signal_id){if(seenSignals.has(detail.signal_id)||!device.value)return;seenSignals.add(detail.signal_id);const thread=data.value.threads.find((t:any)=>t.id===id);if(!thread||!thread.peer_device_id)return;const other=thread.devices.find((d:Device)=>d.id!==device.value?.id);if(!other||!await trusted(device.value,other))return;const result=await api('/threads/'+id+'/signals/'+detail.signal_id),row=result.signal;if(row.sender_device_id===device.value.id)return;const payload=await decrypt(device.value,other,id,row.id,row.envelopes,'signal');if(!payload.signal)return;if(active.value?.id!==id){if(payload.signal.type!=='offer'||callActive.value)return;await open(thread);}emit('incoming',id);await nextTick();await privateCall.value?.receive(payload.signal);return;}if(id&&active.value?.id!==id)return;if(verified.value)await loadMessages();}catch(e){error.value=(e as Error).message;}}
watch(()=>props.threadId,async id=>{if(id&&data.value&&active.value?.id!==id){const thread=data.value.threads.find((t:any)=>t.id===id);if(thread)await open(thread);}});
onMounted(async()=>{window.addEventListener('judibas-e2ee-update',live);window.addEventListener('judibas-e2ee-reconnect',live);try{await refresh();if(props.threadId){const thread=data.value.threads.find((t:any)=>t.id===props.threadId);if(thread)await open(thread);}}catch(e){error.value=(e as Error).message;}});onBeforeUnmount(()=>{void privateCall.value?.hangup();closed=true;generation++;cleanup();draft.value='';device.value=null;window.removeEventListener('judibas-e2ee-update',live);window.removeEventListener('judibas-e2ee-reconnect',live);});
</script>
<template>
<section class="encrypted-workspace" :class="{'has-private-chat':!!active,'show-directory':newChat}">
 <p v-if="error" class="comm-error encrypted-error" role="alert">{{error}}<button @click="error=''">Dismiss</button></p>
 <div v-if="!data" class="encrypted-loading" role="status">Loading private chats...</div>
 <div v-else class="comm-layout encrypted-layout">
  <aside class="comm-sidebar encrypted-sidebar">
   <div class="comm-conversation-heading"><h2>{{data.can_create?'Private chats':'Chats'}}</h2><button v-if="data.can_create&&!legacy" type="button" aria-label="New private conversation" title="New private conversation" :disabled="!device||callActive" @click="newChat=!newChat">+</button></div>
   <input class="comm-filter" v-model="chatFilter" aria-label="Search private conversations" placeholder="Search conversations...">
   <form v-if="newChat&&data.can_create&&device" class="encrypted-create" @submit.prevent="start"><label>Start a private chat<select v-model="target" required><option value="">Select a Communication participant</option><option v-for="person in data.people" :key="person.id" :value="String(person.id)">{{person.name}}</option></select></label><button class="comm-primary" :disabled="busy||!target">{{busy?'Creating...':'Create encrypted chat'}}</button><button type="button" class="encrypted-text-button" @click="newChat=false">Cancel</button></form>
   <nav class="comm-conversations" aria-label="Encrypted conversations"><button v-for="thread in data.threads.filter((t:any)=>(data.can_create?t.peer_name:'Super Admin').toLowerCase().includes(chatFilter.toLowerCase()))" :key="thread.id" :class="{active:active?.id===thread.id}" :disabled="busy||callActive" @click="open(thread)"><span class="comm-private-avatar">{{initials(data.can_create?thread.peer_name:'Super Admin')}}</span><span class="comm-conversation-copy"><strong>{{data.can_create?thread.peer_name:'Super Admin'}}</strong><small>Private conversation</small><p>{{thread.peer_device_id?'End-to-end encrypted':'Invitation sent'}}</p></span><svg class="encrypted-small-lock" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg></button><template v-if="!data.can_create"><button v-for="chat in (regularChats||[]).filter(c=>c.name.toLowerCase().includes(chatFilter.toLowerCase()))" :key="'regular-'+chat.id" :disabled="callActive" @click="emit('regular',chat.id)"><span class="comm-private-avatar">{{initials(chat.name)}}</span><span class="comm-conversation-copy"><strong>{{chat.name}}</strong><p>{{chat.preview}}</p></span></button></template></nav>
   <p v-if="!data.threads.length" class="comm-empty-small">{{legacy?'Previous encrypted conversations are preserved here.':data.can_create?'Start a private conversation using the + button.':'Your private invitations will appear here.'}}</p>
   <button type="button" class="encrypted-back-list" :disabled="callActive" @click="emit('close')">&larr; All chats</button>
  </aside>
  <section class="comm-chat encrypted-chat">
   <header class="comm-chat-heading encrypted-chat-heading"><button type="button" class="encrypted-back" aria-label="Back to chats" :disabled="callActive" @click="emit('close')"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m14 5-7 7 7 7M7 12h14"/></svg></button><span class="comm-private-avatar">{{active?initials(chatName):'P'}}</span><div class="encrypted-chat-identity"><h2>{{active?chatName:'Private chats'}}</h2><p>{{verified?'Private conversation - End-to-end encrypted':active?'Private conversation':'Only Super Admin can start a private conversation'}}</p></div><EncryptedVoiceCall ref="privateCall" v-if="data.calling_enabled&&verified&&active" compact :enabled="verified&&(canCall!==false)&&!voiceRecording" :thread-id="active.id" :name="chatName" :send="sendControl" @active="callState"/><button v-if="data.can_create&&!legacy" type="button" class="encrypted-mobile-create" aria-label="New private conversation" :disabled="!device||callActive" @click="newChat=true">+</button><button v-if="device&&active?.peer_device_id" type="button" class="encrypted-security-button" aria-label="Check chat security" title="Check chat security" @click="securityOpen=!securityOpen"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m12 3 8 4v5c0 5-8 9-8 9s-8-4-8-9V7l8-4Z"/><path d="m8 12 3 3 5-6"/></svg></button></header>
   <div v-if="!device" class="encrypted-state"><span class="encrypted-state-icon" aria-hidden="true"><svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg></span><h3>{{data.threads.length?'Super Admin invited you to a private conversation':'Enable private chats on this browser'}}</h3><p>Your browser keeps the key that opens your private messages. Only you and the selected participant can read them.</p><button v-if="!data.device" class="comm-primary" :disabled="busy" @click="setup">{{busy?'Setting up...':'Register my device'}}</button><small>Use a trusted browser profile. Clearing its site data can permanently lose access.</small></div>
   <div v-else-if="!active" class="encrypted-state"><h3>{{data.can_create?'Start a private conversation':'Choose a conversation'}}</h3><p>{{data.can_create?'Select a conversation, or use + to invite someone.':'Open your private invitation from the Chats list.'}}</p><button v-if="data.can_create&&!legacy" class="comm-primary" @click="newChat=true">New private conversation</button></div>
   <div v-else-if="!active.peer_device_id" class="encrypted-state"><h3>Waiting for the other person</h3><p>Your private invitation is in their Chats list. They need to enable private chat on their browser before you can continue.</p></div>
   <template v-else>
    <div v-if="!verified||securityOpen" class="encrypted-verification"><header><span class="encrypted-state-icon" aria-hidden="true"><svg width="25" height="25" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="m12 3 8 4v5c0 5-8 9-8 9s-8-4-8-9V7l8-4Z"/></svg></span><div><h3>{{verified?'Chat security':'One-time security check'}}</h3><p>You and {{chatName}} should see the <strong>same security code</strong>.</p></div></header><ol><li>Ask {{chatName}} to open this conversation and select the shield icon.</li><li>Compare all the code groups in person or over a trusted phone call. No code needs to be sent to Judibas.</li></ol><div class="encrypted-security-code" aria-label="Conversation security code"><span v-for="(group,index) in securityCode.split(' ')" :key="index">{{group}}</span></div><div class="encrypted-code-actions"><button type="button" class="button" @click="copyCode">Copy security code</button><span v-if="copyNotice" role="status">{{copyNotice}}</span></div><template v-if="!verified"><label class="encrypted-compare-check"><input type="checkbox" v-model="compared">We compared both codes and every group matches.</label><button class="comm-primary" :disabled="busy||!compared" @click="verify">{{busy?'Confirming...':'Confirm matching codes'}}</button></template><template v-else><p class="encrypted-verified">Security check completed on this browser.</p><button type="button" class="button" @click="securityOpen=false">Back to conversation</button></template><details class="encrypted-security-help"><summary>Why check this code?</summary><p>This checks that you are using the intended person's encryption key. It is not a physical fingerprint, password or private key. Compare it once per trusted browser; a key change requires another check. Do not confirm a code supplied only through this unverified conversation.</p></details></div>
    <template v-if="verified"><div class="encrypted-chat-banner"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>Messages and calls are private to the two participants.</div><div class="comm-messages encrypted-messages" aria-label="Encrypted messages"><button v-if="more" class="comm-load-more" :disabled="loading" @click="loadMessages(true)">Load earlier messages</button><p v-if="loading" class="comm-empty-small" role="status">Loading messages...</p><p v-if="!rows.length&&!loading" class="comm-empty-small">Send your first private message.</p><article v-for="row in rows" :key="row.id" class="comm-message" :class="{mine:row.sender_device_id===device.id}"><span class="comm-message-avatar">{{initials(row.sender_device_id===device.id?'You':chatName)}}</span><div class="comm-message-meta"><strong>{{row.sender_device_id===device.id?'You':chatName}}</strong></div><div class="comm-bubble"><p v-if="row.failed" class="encrypted-failure">Message could not be authenticated or decrypted. Its content has not been displayed.</p><template v-else><p>{{row.payload.text}}</p><template v-if="row.payload.file"><a v-if="['image/png','image/jpeg','image/webp'].includes(row.payload.file.type)" :href="row.url" :download="row.payload.file.name" class="comm-chat-image-link"><img class="comm-chat-image" :src="row.url" :alt="row.payload.file.name"></a><VoiceMessage v-if="row.payload.file.type.startsWith('audio/')" :src="row.url"/><a class="encrypted-download" :href="row.url" :download="row.payload.file.name">Download {{row.payload.file.name}}</a></template></template><small class="comm-bubble-time">{{time(row.created_at)}}</small></div></article></div><form class="comm-composer encrypted-composer" :aria-busy="busy" @submit.prevent="send"><div v-if="file" class="comm-composer-context">{{file.name}}<button type="button" @click="file=null">&times;</button></div><div class="comm-composer-row" :class="{'recording-voice':voiceRecording}"><input class="comm-file-input" ref="fileInput" type="file" aria-label="Private file attachment" :disabled="busy" @change="file=($event.target as HTMLInputElement).files?.[0]||null"><button type="button" :disabled="busy||voiceRecording" aria-label="Attach private file" title="Attach file (up to 1 MB)" @click="fileInput?.click()">+</button><VoiceRecorder :max-seconds="180" :key="active.id" :disabled="busy||!!file||!!draft.trim()||callActive||canCall===false" @active="voiceRecording=$event" @ready="voiceReady"/><EmojiPicker v-if="!voiceRecording" mode="composer" @select="draft=(draft+$event).slice(0,10000)"/><textarea v-show="!voiceRecording" aria-label="Private message" v-model="draft" maxlength="10000" rows="1" :disabled="busy" placeholder="Write a private message..." @keydown.enter="onEnter"></textarea><button class="comm-send" :aria-label="busy?'Sending encrypted message':'Send encrypted'" :disabled="busy||voiceRecording||(!draft.trim()&&!file)">{{busy?'Sending...':'Send'}}<span v-if="!busy" aria-hidden="true"> &rarr;</span></button></div><small v-if="!voiceRecording">Enter to send &middot; Shift + Enter for a new line &middot; Files up to 1 MB</small></form></template>
   </template>
  </section>
 </div>
</section>
</template>
